(\textbf{Grothendieck fibration})
		A \emph{Grothendieck fibration} (or \emph{fibration} for short) is a functor $P:
  \relax
  \StrLen{E}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{E}
  \else
    \mathbf{E}
  \fi
 \to 
  \relax
  \StrLen{X}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{X}
  \else
    \mathbf{X}
  \fi
$ such that any arrow $f:X \to P(D)$ in $
  \relax
  \StrLen{X}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{X}
  \else
    \mathbf{X}
  \fi
$ admits a (strong) cartesian lift:
		\begin{equation}

			\begin{tikzcd}[ampersand replacement=\&]
				{
  \relax
  \StrLen{E}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{E}
  \else
    \mathbf{E}
  \fi
} \& {f^*D} \& D \\
				{
  \relax
  \StrLen{X}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{X}
  \else
    \mathbf{X}
  \fi
} \& X \& {P(D)}
				\arrow["{f_D}", from=1-2, to=1-3]
				\arrow["f", from=2-2, to=2-3]
				\arrow["P"', from=1-1, to=2-1]
			\end{tikzcd}
		\end{equation}
		For $f_D$ to be a cartesian lift, it has to be terminal among all morphisms into $D$ and projecting down to $f$, see Definition~\ref{def:cart-arr}. Moreover, we can show these lifts compose: cartesian lifts of $f$ and $g$ compose to give a cartesian lift for $f \fatsemi g$. Furthermore, up to unique vertical isomorphism, the cartesian lift $f_D : f^*D \to D$ is determined uniquely.














		$
  \relax
  \StrLen{E}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{E}
  \else
    \mathbf{E}
  \fi
$ is called the \emph{total category} and $
  \relax
  \StrLen{X}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{X}
  \else
    \mathbf{X}
  \fi
$ the \emph{base category}.

(\textbf{$P$-lenses})
	\label{def:lens}
		Let $P: 
  \relax
  \StrLen{E}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{E}
  \else
    \mathbf{E}
  \fi
 \to 
  \relax
  \StrLen{X}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{X}
  \else
    \mathbf{X}
  \fi
$ be a fibration.
		Its dual fibration ${{P}^{\vee_{}}}: {{
  \relax
  \StrLen{E}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{E}
  \else
    \mathbf{E}
  \fi
}^{\vee_{}}} \to 
  \relax
  \StrLen{X}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{X}
  \else
    \mathbf{X}
  \fi
$ is called the \textbf{fibration of $P$-lenses}, and morphisms in ${{
  \relax
  \StrLen{E}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{E}
  \else
    \mathbf{E}
  \fi
}^{\vee_{}}}$ are \textbf{$P$-lenses}.

\label{def:dc}
		The \textbf{(simple) Dialectica category} $\mathbf{Dial}_\times(
  \relax
  \StrLen{C}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{C}
  \else
    \mathbf{C}
  \fi
)$ has
		\begin{enumerate}
			\item as objects, triples
			\begin{equation}
				(U : 
  \relax
  \StrLen{C}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{C}
  \else
    \mathbf{C}
  \fi
, X : 
  \relax
  \StrLen{C}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{C}
  \else
    \mathbf{C}
  \fi
, \alpha : \mathrm{Sub}(U \times X))
			\end{equation}
			meaning $\alpha$ is a subobject of $U \times X$,
			\item as morphisms $(U,X,\alpha) \to (V,Y,\beta)$, triples
			\begin{eqalign}
				&f: U \to V,\\
				&f^\sharp : U \times Y \to X,\\
				\forall u:U, y:Y, \quad &\alpha(u, f^\sharp(u, y)) \subseteq \beta(f(u), y)
			\end{eqalign}
		\end{enumerate}

Let $\boldsymbol{P} = (
  \relax
  \StrLen{E}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{E}
  \else
    \mathbf{E}
  \fi
_n \xrightarrow{P_n} \cdots \xrightarrow{P_3} 
  \relax
  \StrLen{E}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{E}
  \else
    \mathbf{E}
  \fi
_2 \xrightarrow{P_2} 
  \relax
  \StrLen{E}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{E}
  \else
    \mathbf{E}
  \fi
_1 \xrightarrow{P_1} 
  \relax
  \StrLen{E}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{E}
  \else
    \mathbf{E}
  \fi
_0)$ be a sequence of $n$ fibrations (a  \textbf{tower of fibrations of height} $n$).
		The \textbf{iterated dual} of $\boldsymbol{P}$ is defined inductively on its length $1 \leq k < n$ as follows:
		\begin{itemize}
			\item $k=1:$
			\begin{equation}
				{{(
  \relax
  \StrLen{E}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{E}
  \else
    \mathbf{E}
  \fi
_1 \xrightarrow{P_1} 
  \relax
  \StrLen{E}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{E}
  \else
    \mathbf{E}
  \fi
_0)}^{\vee_{1}}} = {{
  \relax
  \StrLen{E}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{E}
  \else
    \mathbf{E}
  \fi
_1}^{\vee_{
  \relax
  \StrLen{E}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{E}
  \else
    \mathbf{E}
  \fi
_0}}} \xrightarrow{{{P_1}^{\vee_{
  \relax
  \StrLen{E}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{E}
  \else
    \mathbf{E}
  \fi
_0}}}} 
  \relax
  \StrLen{E}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{E}
  \else
    \mathbf{E}
  \fi
_0
			\end{equation}
			\item $1 < k < n:$
			\begin{equation}
				{{(
  \relax
  \StrLen{E}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{E}
  \else
    \mathbf{E}
  \fi
_{k+1} \xrightarrow{P_{k+1}} \cdots \xrightarrow{P_2} 
  \relax
  \StrLen{E}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{E}
  \else
    \mathbf{E}
  \fi
_1 \xrightarrow{P_1} 
  \relax
  \StrLen{E}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{E}
  \else
    \mathbf{E}
  \fi
_0)}^{\vee_{k+1}}}
				=
				{{\left({{(
  \relax
  \StrLen{E}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{E}
  \else
    \mathbf{E}
  \fi
_{k+1} \xrightarrow{P_{k+1}} \cdots \xrightarrow{P_{2}} 
  \relax
  \StrLen{E}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{E}
  \else
    \mathbf{E}
  \fi
_1)}^{\vee_{k}}}\right)}^{\vee_{
  \relax
  \StrLen{E}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{E}
  \else
    \mathbf{E}
  \fi
_0}}}\xrightarrow{{{P_1}^{\vee_{
  \relax
  \StrLen{E}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{E}
  \else
    \mathbf{E}
  \fi
_0}}}} 
  \relax
  \StrLen{E}[\catarglen]
  \ifnum\catarglen=1
    \mathcal{E}
  \else
    \mathbf{E}
  \fi
_0
			\end{equation}
		\end{itemize}
